// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The difference is in proxiableUUID() which returns a hardcoded zero constant in the mutant
        // vs ERC1967Utils.IMPLEMENTATION_SLOT in the reference.
        // We can observe this by calling the public view function proxiableUUID() and checking its return value.
        // Since the contract is not delegated, this call is allowed and returns the implementation slot in the reference.
        // We just need to call it and compare.

        bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc; // ERC1967Utils.IMPLEMENTATION_SLOT
        bytes32 actual = c.proxiableUUID();
        assertTrue(actual == expected);
    }
}
